scripts.醉郎中死亡.txt:
//醉郎中死亡

	Say("醉郎中：啊呀——我不甘心！");
	Say("张琳心：武林中有多少人为了秘笈神兵而落到这样的下场……", 24);
	Say("独孤剑：不错。琳儿，不如我们把它毁掉算了……", 1);
	Say("张琳心：傻瓜！毁掉这套花了无数心血制成的宝物，岂不更是罪过。宝物本无罪，只是看使用它的人。独孤哥哥，你用这套神兵惩奸除恶，行侠仗义，才不辜负它原来的主人。", 21);
	Say("独孤剑：你说的对。", 2);
	AddGoods("Goods016_霁云之胆.ini");
	Assign($Sub,180);
	Return;

traps.trap01.txt:
// 切换到map048华山脚下

	If ($Event << 350) @Eventless350;
	If ($Event == 370) @Event370;
	
	FadeOut();
	Assign($Knock, 0);
	SaveNpc();
	ClearBody();
	SaveObj();
	LoadMap("map048_华山脚下.map");
	LoadNpc("map048.npc");
	LoadObj("map048.obj");
	SetPlayerPos(16, 69);
	SetPlayerDir(1);
	FadeIn();
	Return;
	
@Eventless350:
	Say("独孤剑：此刻还是尽快上山的好。", 1);
	Return;
	
@Event370:
	If ($Sub == 171) @Sub171;
	
	Say("张琳心：独孤哥哥，方大侠说去少林的路在后山。", 21);
	Return;	
	
@Sub171:
	Say("醉郎中：小子，你休想逃走。");
	Return;

