traps.trap03.txt:
// 栈桥前的trap

	If ($Event == 320) @Event320;
	Return;
	
@Event320:	
	DisableNpcAI();
	SetNpcKind("李三", 0);
	PlayerGoto(9, 21);
	SetPlayerDir(6);
	NpcGoto("李三", 10, 21);
	SetNpcDir("李三", 2);
	Say("李三：这里就是一秤峰顶了，对面的山头便是朝阳峰。过了这桥，两位就上了华山的正道。俺们采药打柴的，就不方便走那条路了，俺只能带到这了。", 70);
	Say("独孤剑：多谢李大哥，咱们后会有期。", 2);
	Say("李三：二位多保重，俺走了。", 70);
	Say("张琳心：多谢。", 21);
	NpcGoto("李三", 18, 34);
	DelNpc("李三");
	SaveNpc();
	Watch("独孤剑", "张琳心", 0);
	Say("独孤剑：我们走吧。", 1);
	SetNpcKind("张琳心", 3);
	Assign($Event, 330);
	SetMapTrap(3, "");
	SetMapTrap(4, "trap04.txt");
	EnableNpcAI();
	Return;

